}

import requests
from shipping_client import get_rates

FALLBACK_RATES = {"standard": 4.99}

def checkout_rates(cart_id: str) -> dict:
    try:
        return get_rates(cart_id)
    except requests.Timeout:
        # Shipping is slow or down: show flat rates instead of failing
        return FALLBACK_RATES

import requests

SHIPPING_URL = "http://shipping.internal/rates"

def get_rates(cart_id: str) -> dict:
    response = requests.get(SHIPPING_URL, params={"cart": cart_id})
    response.raise_for_status()
    return response.json()

