async function fetchWithRetry(url: string): Promise<Response> {
  while (true) {
    const res = await fetch(url, { signal: AbortSignal.timeout(30_000) })
    if (res.status !== 429) return res
  }
}

async function fetchWithRetry(url: string, maxAttempts = 5): Promise<Response> {
  for (let attempt = 1; ; attempt++) {
    const res = await fetch(url)
    if (res.status !== 429 || attempt === maxAttempts) return res
    const retryAfter = Number(res.headers.get('Retry-After'))
    const backoff = 2 ** attempt * 250 + Math.random() * 250
    await sleep(retryAfter > 0 ? retryAfter * 1000 : backoff)
  }
}

async function fetchWithRetry(url: string): Promise<Response> {
